// Constrain inputs so that a + b never overflows for any valid C++ int width.
// Per the C++ standard, int is guaranteed to be at least 16 bits (range >= [-32767, 32767]).
// Choose a and b from [-10000, 10000], so their sum is in [-20000, 20000], which is always representable.
unsigned int ru = *FUZZ_PARAM(unsigned int);
unsigned int rv = *FUZZ_PARAM(unsigned int);
const int kRange = 10000; // safe across all conforming platforms
int a = (int)((int)(ru % (unsigned int)(2 * kRange + 1)) - kRange);
int b = (int)((int)(rv % (unsigned int)(2 * kRange + 1)) - kRange);

// Call the target function; with the above constraints, addition cannot overflow.
int sum = coreutils_stub_add(a, b);

// Validate correctness using a wide type to avoid intermediate overflow.
long long expected = (long long)a + (long long)b;
FUZZ_ASSERT((long long)sum == expected, "coreutils_stub_add must equal the mathematical sum without overflow");

// Output a managed result so downstream stubs can consume it.
int *coreutils_stub_add_result = new int(sum);
FUZZ_SET_ATTR_STR(coreutils_stub_add_result, "source", "coreutils_stub_add");

